select l_returnflag, l_linestatus, sum(l_quantity) as sum_qty, sum(l_extendedprice) as sum_base_price,
       sum(l_extendedprice * (1 - l_discount)) as sum_disc_price, sum(l_extendedprice * (1 - l_discount) * (1 + l_tax)) as sum_charge,
       avg(l_quantity) as avg_qty, avg(l_extendedprice) as avg_price, avg(l_discount) as avg_disc, count(*) as count_order
from (SELECT "c_custkey" AS c_custkey, "c_name" AS c_name, "c_address" AS c_address, "c_nationkey" AS c_nationkey, "c_phone" AS c_phone, "c_acctbal" AS c_acctbal, "c_mktsegment" AS c_mktsegment, "c_comment" AS c_comment, "c_orders.o_orderkey" AS o_orderkey, "c_orders.o_orderstatus" AS o_orderstatus, "c_orders.o_totalprice" AS o_totalprice, "c_orders.o_orderdate" AS o_orderdate, "c_orders.o_orderpriority" AS o_orderpriority, "c_orders.o_clerk" AS o_clerk, "c_orders.o_shippriority" AS o_shippriority, "c_orders.o_comment" AS o_comment, "c_orders.o_lineitems.l_partkey" AS l_partkey, "c_orders.o_lineitems.l_suppkey" AS l_suppkey, "c_orders.o_lineitems.l_linenumber" AS l_linenumber, "c_orders.o_lineitems.l_quantity" AS l_quantity, "c_orders.o_lineitems.l_extendedprice" AS l_extendedprice, "c_orders.o_lineitems.l_discount" AS l_discount, "c_orders.o_lineitems.l_tax" AS l_tax, "c_orders.o_lineitems.l_returnflag" AS l_returnflag, "c_orders.o_lineitems.l_linestatus" AS l_linestatus, "c_orders.o_lineitems.l_shipdate" AS l_shipdate, "c_orders.o_lineitems.l_commitdate" AS l_commitdate, "c_orders.o_lineitems.l_receiptdate" AS l_receiptdate, "c_orders.o_lineitems.l_shipinstruct" AS l_shipinstruct, "c_orders.o_lineitems.l_shipmode" AS l_shipmode, "c_orders.o_lineitems.l_comment" AS l_comment FROM read_parquet_flat('nestedcustomer.parquet')) where l_shipdate <= date '1998-12-01' - interval '90' day
group by l_returnflag, l_linestatus order by l_returnflag, l_linestatus
